import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

import numpy as np
from scipy import stats

# Filter to counted rows only
df_counted = df[df['row_kind'] == 'counted'].copy()

# Parse dates
df_counted['Admit Date'] = pd.to_datetime(df_counted['Admit Date'], errors='coerce')
df_counted['Discharge Date'] = pd.to_datetime(df_counted['Discharge Date'], errors='coerce')

# Use provided length_of_stay if available, else compute
if 'length_of_stay' not in df_counted.columns:
    df_counted['length_of_stay'] = (df_counted['Discharge Date'] - df_counted['Admit Date']).dt.days

# --- EDA ---
try:
    eda_cols = ['Total Charges', 'length_of_stay']
    eda_result = {}
    for col in eda_cols:
        if col in df_counted.columns:
            s = df_counted[col].dropna()
            eda_result[col] = {
                "mean": float(s.mean()),
                "std": float(s.std()),
                "min": float(s.min()),
                "max": float(s.max()),
                "median": float(s.median()),
                "count": int(s.count())
            }
    result['eda_summary'] = eda_result
except Exception:
    pass

# --- CORRELATIONS ---
try:
    num_df = df_counted[['Total Charges', 'length_of_stay']].dropna()
    corr_dict = {}
    cols = num_df.columns.tolist()
    for i in range(len(cols)):
        for j in range(i+1, len(cols)):
            c1, c2 = cols[i], cols[j]
            r, _ = stats.pearsonr(num_df[c1], num_df[c2])
            if abs(r) >= 0.2:
                corr_dict[f"{c1}__{c2}"] = round(float(r), 4)
    result['correlations'] = corr_dict
except Exception:
    pass

# --- SEGMENTATION ---
try:
    seg_results = []
    segment_cols = ['Encounter Type', 'Department', 'Discharge Disposition']
    metric_col = 'Total Charges'

    for seg_col in segment_cols:
        if seg_col not in df_counted.columns:
            continue
        grp = df_counted.groupby(seg_col)[metric_col].mean().nlargest(10)
        seg_results.append({
            "segment_column": seg_col,
            "metric_column": metric_col,
            "aggregation": "mean",
            "label": None,
            "results": [{"name": str(k), "value": round(float(v), 2)} for k, v in grp.items()]
        })

    # LOS by segment
    for seg_col in ['Encounter Type', 'Department']:
        if seg_col not in df_counted.columns:
            continue
        grp = df_counted.groupby(seg_col)['length_of_stay'].mean().nlargest(10)
        seg_results.append({
            "segment_column": seg_col,
            "metric_column": "length_of_stay",
            "aggregation": "mean",
            "label": None,
            "results": [{"name": str(k), "value": round(float(v), 2)} for k, v in grp.items()]
        })

    # Discharges count by Department
    ip_mask = df_counted['Encounter Type'].str.lower().isin(['inpatient', 'ip', 'inpt', 'i'])
    ip_df = df_counted[ip_mask & df_counted['Discharge Date'].notna()]
    if len(ip_df) > 0:
        grp_dept = ip_df.groupby('Department')['Encounter ID'].count().nlargest(10)
        seg_results.append({
            "segment_column": "Department",
            "metric_column": "Encounter ID",
            "aggregation": "count",
            "label": "discharges_by_department",
            "results": [{"name": str(k), "value": float(v)} for k, v in grp_dept.items()]
        })

    # 30-day readmission rate by Department
    try:
        excl_disp = {20, 7, 2, 5, 43, 66, 82, 85, 88, 93, 94}
        excl_str = {'expired','died','deceased','ama','left against medical advice',
                    'against medical advice','transferred','transfer to acute care','transfer acute'}
        ip_full = df_counted[ip_mask & df_counted['Discharge Date'].notna()].copy()
        ip_full['Discharge Disposition'] = ip_full['Discharge Disposition'].astype(str).str.strip().str.lower()
        def is_excluded(d):
            try:
                return int(float(d)) in excl_disp
            except Exception:
                return d in excl_str
        ip_full['excl'] = ip_full['Discharge Disposition'].apply(is_excluded)
        last_admit = df_counted['Admit Date'].max()
        cutoff = last_admit - pd.Timedelta(days=30)
        eligible = ip_full[~ip_full['excl'] & (ip_full['Discharge Date'] <= cutoff)].copy()
        if len(eligible) > 0:
            all_ip = df_counted[ip_mask][['MRN','Admit Date']].dropna()
            eligible = eligible.merge(all_ip.rename(columns={'Admit Date':'next_admit','MRN':'MRN2'}),
                                      left_on='MRN', right_on='MRN2', how='left')
            eligible['days_to_next'] = (eligible['next_admit'] - eligible['Discharge Date']).dt.days
            readmit = eligible[(eligible['days_to_next'] > 0) & (eligible['days_to_next'] <= 30)]
            readmit_enc = readmit['Encounter ID'].unique()
            eligible['readmitted'] = eligible['Encounter ID'].isin(readmit_enc)
            ra_by_dept = eligible.groupby('Department').apply(
                lambda x: x['readmitted'].any() if len(x) == 0 else x['readmitted'].sum() / len(x)
            ).reset_index()
            ra_by_dept.columns = ['Department', 'rate']
            seg_results.append({
                "segment_column": "Department",
                "metric_column": "Discharge Date",
                "aggregation": "ratio",
                "label": "readmission_rate",
                "results": [{"name": str(r2['Department']), "value": round(float(r2['rate']), 4)}
                            for _, r2 in ra_by_dept.iterrows()]
            })
    except Exception:
        pass

    result['segments'] = seg_results
except Exception:
    pass

# --- ANOMALIES ---
try:
    anomalies = []
    anom_cols = ['Total Charges', 'length_of_stay']
    for col in anom_cols:
        if col not in df_counted.columns:
            continue
        s = df_counted[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = 0
        if s.min() < 0:
            shift = -s.min() + 1
        if abs(skew) > 2:
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
        Q1, Q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        IQR = Q3 - Q1
        lo_t, hi_t = Q1 - 3*IQR, Q3 + 3*IQR
        if abs(skew) > 2:
            lo_orig = float(np.expm1(lo_t) - shift)
            hi_orig = float(np.expm1(hi_t) - shift)
        else:
            lo_orig, hi_orig = float(lo_t), float(hi_t)
        flagged = df_counted[(s_t < lo_t) | (s_t > hi_t)][col]
        pct = len(flagged) / len(s)
        if pct > 0.05:
            anomalies.append({
                "column": col, "row_index": None, "value": None,
                "expected_range": f"{lo_orig:.2f} to {hi_orig:.2f}",
                "severity": "low",
                "explanation": f"{col} is heavy-tailed; more than 5% of values fall outside the extreme IQR boundary"
            })
            continue
        for idx, val in flagged.items():
            if len(anomalies) >= 25:
                break
            val_t = np.log1p(val + shift) if abs(skew) > 2 else val
            diff_hi = (val_t - (Q3 + 3*IQR)) / IQR if val_t > Q3 else 0
            diff_lo = ((Q1 - 3*IQR) - val_t) / IQR if val_t < Q1 else 0
            diff = max(diff_hi, diff_lo)
            if diff > 2:
                sev = "critical"
            elif diff > 1:
                sev = "high"
            else:
                sev = "medium"
            anomalies.append({
                "column": col,
                "row_index": int(idx),
                "value": float(val),
                "expected_range": f"{lo_orig:.2f} to {hi_orig:.2f}",
                "severity": sev,
                "explanation": f"{col} value of {val:.2f} lies outside expected range {lo_orig:.2f} to {hi_orig:.2f}"
            })
    result['anomalies'] = anomalies
except Exception:
    pass

# --- TRENDS ---
try:
    df_counted['month'] = df_counted['Discharge Date'].dt.to_period('M')
    monthly = df_counted.groupby('month')['Total Charges'].mean().sort_index()
    trends = []
    if len(monthly) >= 2:
        periods = monthly.index.tolist()
        pct_changes = []
        for i in range(1, len(monthly)):
            prev = monthly.iloc[i-1]
            curr = monthly.iloc[i]
            if prev != 0:
                pct_changes.append((curr - prev) / prev * 100)
        if pct_changes:
            avg_pct = float(np.mean(pct_changes))
            direction = "up" if avg_pct > 1 else ("down" if avg_pct < -1 else "flat")
            trends.append({
                "column": "Total Charges",
                "period": "MoM",
                "direction": direction,
                "pct_change": round(avg_pct, 2),
                "segment": None
            })

    # LOS trend
    monthly_los = df_counted.groupby('month')['length_of_stay'].mean().sort_index()
    if len(monthly_los) >= 2:
        pct_los = []
        for i in range(1, len(monthly_los)):
            prev = monthly_los.iloc[i-1]
            curr = monthly_los.iloc[i]
            if prev != 0:
                pct_los.append((curr - prev) / prev * 100)
        if pct_los:
            avg_los_pct = float(np.mean(pct_los))
            dir_los = "up" if avg_los_pct > 1 else ("down" if avg_los_pct < -1 else "flat")
            trends.append({
                "column": "length_of_stay",
                "period": "MoM",
                "direction": dir_los,
                "pct_change": round(avg_los_pct, 2),
                "segment": None
            })
    result['trends'] = trends
except Exception:
    pass

# --- FORECASTING ---
try:
    monthly_tc = df_counted.groupby('month')['Total Charges'].mean().sort_index()
    if len(monthly_tc) >= 3:
        x = np.arange(len(monthly_tc))
        y = monthly_tc.values.astype(float)
        slope, intercept, _, _, _ = stats.linregress(x, y)
        forecast_pts = []
        last_period = monthly_tc.index[-1]
        for step in range(1, 4):
            next_period = last_period + step
            pred = intercept + slope * (len(monthly_tc) - 1 + step)
            forecast_pts.append({"period": str(next_period), "value": round(float(pred), 2)})
        result['forecast_points'] = forecast_pts
except Exception:
    pass

# --- ASSUMPTIONS ---
result['assumptions'] = [
    "Only 'counted' rows used for all KPIs and figures.",
    "length_of_stay taken from provided column; same-day = 0 days.",
    "Readmission rate excludes dispositions for death, AMA, and transfer per domain rules.",
    "Discharges in last 30 days of data excluded from readmission denominator.",
    "Forecasting uses linear regression on monthly mean Total Charges; short horizon only."
]

# ─── Guaranteed EDA + chart distributions + briefing (always runs) ───

try:
