                'count': int(_s.count()),
            }
except Exception:
    pass

try:
    if 'Total Charges' in df.columns and pd.api.types.is_numeric_dtype(df['Total Charges']):
        _col_data = df['Total Charges'].dropna()
        if len(_col_data) >= 5:
            _n_bins = min(10, max(2, _col_data.nunique()))
            _bins = pd.cut(_col_data, bins=_n_bins)
            _vc = _bins.value_counts().sort_index()
            result['distributions']['Total Charges'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items() if _v > 0
            ]
except Exception:
    pass

try:
    if 'Patient ZIP' in df.columns:
        _vc = df['Patient ZIP'].value_counts().head(10)
        if len(_vc) > 0:
            result['distributions']['Patient ZIP'] = [
