try:
    if 'Department' in df.columns:
        _vc = df['Department'].value_counts().head(10)
        if len(_vc) > 0:
            result['distributions']['Department'] = [
                {'label': str(_k), 'count': int(_v)} for _k, _v in _vc.items()
            ]
except Exception:
